function canon(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v) ?? "undefined";
  if (Array.isArray(v)) return "[" + v.map(canon).join(",") + "]";
  const o = v as Record<string, unknown>;
  return "{" + Object.keys(o).sort().map((k) => JSON.stringify(k) + ":" + canon(o[k])).join(",") + "}";
}

describe("src/lib/office-truth.ts.getJson (forge characterization #241)", () => {
  const fn = (mod as Record<string, unknown>)["getJson"] as (...a: unknown[]) => unknown;
  test("case 1: captured output of getJson([1,\"hello\",true])", async () => {
    const actual = await fn(...[1,"hello",true] as unknown[]);
    expect(canon(actual)).toBe("null");
  });
  test("case 2: captured output of getJson([\"A-B\",false,[1,2,3]])", async () => {
    const actual = await fn(...["A-B",false,[1,2,3]] as unknown[]);
    expect(canon(actual)).toBe("null");
  });
  test("case 3: captured output of getJson([true,[],{}])", async () => {
    const actual = await fn(...[true,[],{}] as unknown[]);
    expect(canon(actual)).toBe("null");
  });
});

